# email_service.rb
require 'json'
require 'ostruct'

module EmailService
  ALLOWED_CONFIG_KEYS = %w[smtp_host smtp_port from_address reply_to subject_prefix].freeze
  ADMIN_KEYS = %w[bcc_address rate_limit_bypass debug_mode relay_host].freeze

  class Configuration
    attr_accessor :smtp_host, :smtp_port, :from_address, :reply_to,
                  :subject_prefix, :bcc_address, :rate_limit_bypass,
                  :debug_mode, :relay_host, :api_key

    def initialize
      @smtp_host = 'localhost'
      @smtp_port = 587
      @from_address = 'noreply@example.com'
      @reply_to = nil
      @subject_prefix = ''
      @bcc_address = nil
      @rate_limit_bypass = false
      @debug_mode = false
      @relay_host = nil
      @api_key = ENV['EMAIL_API_KEY'] || 'default-key'
    end
  end

  class PolicyEnforcer
    def initialize(environment)
      @environment = environment
    end

    def permitted_keys(user_role)
      base_keys = ALLOWED_CONFIG_KEYS.dup
      if @environment == 'production'
        base_keys
      else
        # In non-production, admins get extended access
        base_keys + (user_role == 'admin' ? ADMIN_KEYS : [])
      end
    end

    def filter_params(params, user_role)
      allowed = permitted_keys(user_role)
      params.select { |k, _v| allowed.include?(k.to_s) }
    end
  end

  class Mailer
    attr_reader :config

    def initialize(environment: nil)
      @environment = environment || ENV['RACK_ENV'] || 'development'
      @config = Configuration.new
      @policy = PolicyEnforcer.new(@environment)
      @send_count = 0
      @max_sends_per_minute = 10
    end

    def configure(params, user_role: 'user')
      filtered = @policy.filter_params(params, user_role)
      apply_configuration(filtered)
    end

    def configure_from_environment
      env_config = extract_env_config
      apply_configuration(env_config)
    end

    def send_email(to:, subject:, body:, options: {})
      return { error: 'rate limited' } if rate_limited?

      full_subject = "#{@config.subject_prefix}#{subject}"
      envelope = build_envelope(to, full_subject, body, options)
      deliver(envelope)
    end

    private

    def apply_configuration(params)
      params.each do |key, value|
        setter = "#{key}="
        @config.send(setter, value) if @config.respond_to?(setter)
      end
    end

    def extract_env_config
      config = {}
      ENV.each do |key, value|
        if key.start_with?('EMAIL_CONFIG_')
          config_key = key.sub('EMAIL_CONFIG_', '').downcase
          config[config_key] = coerce_value(value)
        end
      end
      config
    end

    def coerce_value(value)
      case value
      when 'true' then true
      when 'false' then false
      when /\A\d+\z/ then value.to_i
      else value
      end
    end

    def rate_limited?
      return false if @config.rate_limit_bypass
      @send_count >= @max_sends_per_minute
    end

    def build_envelope(to, subject, body, options)
      envelope = {
        from: @config.from_address,
        to: to,
        subject: subject,
        body: body,
        reply_to: @config.reply_to
      }
      envelope[:bcc] = @config.bcc_address if @config.bcc_address
      envelope.merge(options)
    end

    def deliver(envelope)
      host = @config.relay_host || @config.smtp_host
      @send_count += 1
      { status: 'sent', host: host, envelope: envelope }
    end
  end

  class ServiceEndpoint
    def initialize
      @mailer = Mailer.new
      @mailer.configure_from_environment
    end

    def handle_configure(request_params, session)
      user_role = session[:role] || 'user'
      @mailer.configure(request_params, user_role: user_role)
      { status: 'configured' }
    end

    def handle_send(request_params, session)
      to = request_params.delete('to') || request_params.delete(:to)
      subject = request_params.delete('subject') || request_params.delete(:subject)
      body = request_params.delete('body') || request_params.delete(:body)
      @mailer.send_email(to: to, subject: subject, body: body, options: request_params)
    end
  end
end
